import {esc,codeBadge} from './shared.js';
import {library} from '../reference-model.js';
import {seasonRules} from '../data/season-policy.js';
export function referenceArticle(f){
  const {studyStyle:style,studyVariant:variant,studyAccessory:accessory}=f;
  return `<article id="formula-reader" tabindex="-1" class="fl-formula fl-study"><header><h2>${esc(f.title)}</h2></header>
  <div class="fl-study-body"><figure class="fl-study-hero"><button class="fl-image-button" data-study-image="true" aria-label="Enlarge: ${esc(variant.title)}"><img src="${variant.src}" alt="${esc(variant.alt)}" width="825" height="1100" fetchpriority="high"><span>AI illustration</span><small>Enlarge ↗</small></button></figure>
  <div class="fl-study-controls"><h3>${esc(style.name)}</h3>
  <div class="fl-palette-heading"><span class="eyebrow">OUTFIT COLORS</span><small>${style.variants.length} versions</small></div>
  <div class="fl-palette-picker" aria-label="Choose a palette">${style.variants.map(v=>`<button data-study-palette="${v.id}" aria-pressed="${v.id===variant.id}" title="${esc(v.title)}"><span class="fl-palette-dots" aria-hidden="true">${v.palette.map(([name,hex])=>`<i style="background:${hex}"></i>`).join('')}</span><span>${esc(v.palette.map(([name])=>name).join(' × '))}</span><b aria-hidden="true">${v.id===variant.id?'✓':''}</b></button>`).join('')}</div>
  <span class="visually-hidden" aria-live="polite">Current palette: ${esc(variant.title)}</span>
  ${style.accessories?`<details class="fl-accessory-options" ${accessory!=='none'?'open':''}><summary>${style.accessories.some(a=>a.id==='bag')?'Bag Options':'Neckline Details'}</summary><div class="fl-accessory-picker" role="group" aria-label="Optional details for this look">${style.accessories.map(a=>`<button class="btn" data-study-accessory="${a.id}" aria-pressed="${accessory===a.id}">${esc(a.name)}</button>`).join('')}</div></details>`:''}
  <div class="fl-actions"><button class="btn primary" data-scroll-matches>My Clothes & Gaps ↓</button></div>
  <dl class="fl-wear-tips">${style.tips.map(([label,text])=>`<div><dt>${esc(label)}</dt><dd>${esc(text)}</dd></div>`).join('')}</dl>
  </div></div>
  <details class="fl-reference-drawer"><summary>About This Reference <span>Color and styling variations</span></summary><p>${style.evidence?esc(style.evidence):'This look explores colors and styling rather than reproducing a reference item for item.'} The original author and source link have not been verified.</p></details></article>`;
}
export function formulaImageDialog(formula,images,index){const im=images[index];return `<div class="dialog-head"><span class="eyebrow">${im.kind==='ai'?'AI illustration · Not actual garments':'Original inspiration · Screen photo'}</span><button class="close-btn" data-close="formula-image" aria-label="Close reference image">×</button></div><div class="fl-lightbox"><img src="${im.src}" alt="${esc(im.alt)}"><div>${formula.studyStyle?codeBadge(formula.studyStyle):''}<h2 id="formula-image-title">${esc(im.title)}</h2><p>${esc(im.note)}</p><p class="sources">${im.kind==='ai'?'Generated images illustrate layers and colors. Details may vary; these clothes are not verified wardrobe items.':'The original author and link are unverified. Screen photography may alter colors and does not establish material.'}</p><div class="fl-lightbox-controls"><button class="btn" data-gallery-step="-1" aria-label="Previous reference image" ${index===0?'disabled':''}>←</button><span aria-live="polite">${index+1} / ${images.length}</span><button class="btn" data-gallery-step="1" aria-label="Next reference image" ${index===images.length-1?'disabled':''}>→</button></div></div></div>`;}
export function formulaSources(){return `<div class="dialog-head"><h2 id="source-title">Sources & Seasons</h2><button class="close-btn" data-close="formula-sources" aria-label="Close source details">×</button></div><section class="fl-source"><h3>About the Illustrations</h3><p>AI images compare layers and colors; they are not garment photos or personal try-ons. Check materials, thickness and warmth against real items.</p></section><section class="fl-source"><h3>Season Classification</h3><p>Classification follows the rules below, stopping at the first match. Each look appears once. Seasons aid browsing and do not guarantee suitability for weather or warmth.</p><ol>${seasonRules.map(([name,rule])=>`<li><b>${name}</b>: ${esc(rule)}</li>`).join('')}</ol></section>${library.sources.map(s=>`<section class="fl-source"><h3>${s.url?`<a href="${s.url}" target="_blank" rel="noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}</h3><p>${esc(s.text)}</p></section>`).join('')}`;}
